# Ruby port of src/scripts/nogame.lua: the animated "no-game" screen shown when
# `love` is launched with no game. A box2d "duckloon" hangs from a physics chain
# spelling "nogame", over parallax cloud layers. boot.rb calls Love.nogame (which
# installs the load/update/draw/... callbacks) when there is no game source, and
# love_mrb.cpp boots this pipeline for the no-argument case.
#
# The keyword-argument Love:: API replaces the positional love.* one; the 30log
# class helper becomes plain Ruby classes; fixed-timestep physics with State
# interpolation is preserved. The base64 PNG art below is extracted verbatim from
# nogame.lua by testing/mruby/tools/extract_nogame_art.py.

module Love
  # Base64-encoded PNG art, extracted verbatim from src/scripts/nogame.lua
  # (regenerate with testing/mruby/tools/extract_nogame_art.py). Keyed
  # [group][dpiscale][name]; decoded to textures in Scene#load.
  NOGAME_ART = {
    'bg' => {
      1 => {
        'cloud_1' => '',
        'cloud_2' => '',
        'cloud_3' => '',
        'cloud_4' => '',
      },
      2 => {
        'cloud_1' => '',
        'cloud_2' => '',
        'cloud_3' => '',
        'cloud_4' => '',
      },
    },
    'chain' => {
      1 => {
        'a' => '',
        'e' => '',
        'g' => '',
        'm' => '',
        'n' => '',
        'o' => '',
        'square' => '',
      },
      2 => {
        'a' => '',
        'e' => '',
        'g' => '',
        'm' => '',
        'n' => '',
        'o' => '',
        'square' => '',
      },
    },
    'duckloon' => {
      1 => {
        'blink' => '',
        'normal' => '',
      },
      2 => {
        'blink' => '',
        'normal' => '',
      },
    },
  }.freeze

  # All of the screen's logic lives here. The modules are registered natively
  # before this file is evaluated, so aliasing them as constants is safe.
  module NoGameScreen
    G = Love::Graphics
    P = Love::Physics
    M = Love::Math

    # Holds two (x, y, angle) snapshots of a body and interpolates between them,
    # so the 20 Hz physics can be drawn smoothly at the render framerate.
    class State
      def initialize(body)
        @t0 = 0.0
        @x0 = body.get_x; @y0 = body.get_y; @r0 = body.get_angle
        @t1 = @t0; @x1 = @x0; @y1 = @y0; @r1 = @r0
      end

      def save(body, t)
        @t0 = @t1; @x0 = @x1; @y0 = @y1; @r0 = @r1
        @t1 = t; @x1 = body.get_x; @y1 = body.get_y; @r1 = body.get_angle
      end

      def get(t)
        t = t < @t0 ? @t0 : (t > @t1 ? @t1 : t)
        denom = @t1 - @t0
        p = denom.zero? ? 0.0 : (t - @t0) / denom
        [@x0 + p * (@x1 - @x0), @y0 + p * (@y1 - @y0), @r0 + p * (@r1 - @r0)]
      end
    end

    # Decides when the Duckloon's eyes are closed.
    class Blink
      def initialize
        @closed_t = 0.0
        @next_blink_t = 5.0
      end

      def update(dt)
        @next_blink_t = [0.0, @next_blink_t - dt].max
        @closed_t = [0.0, @closed_t - dt].max
        if @next_blink_t.zero?
          @next_blink_t = 5 + M.random(min: 0, max: 3)
          @closed_t = 0.1
        end
      end

      def closed?
        @closed_t > 0
      end
    end

    # Duckloon (TM): a triangular dynamic body, pinned in place, that the chain
    # hangs from.
    class Duckloon
      attr_reader :body

      def initialize(world, x, y, images)
        @body = P.new_body(world: world, x: x, y: y, type: "dynamic")
        @body.set_linear_damping(damping: 0.8)
        @body.set_angular_damping(damping: 0.8)
        @shape = P.new_polygon_shape(body: @body, points: [-55, -60, 0, 90, 55, -60])
        @shape.set_restitution(restitution: 0.5)
        @img_normal = images[:duckloon_normal]
        @img_blink  = images[:duckloon_blink]
        @blink = Blink.new
        @pin = P.new_mouse_joint(body: @body, x: x, y: y - 80)
        @state = State.new(@body)
      end

      def step(g_step)
        @state.save(@body, g_step)
        @body.apply_force(x: M.random(min: 30, max: 50), y: 0) if (g_step % 5).floor.zero?
      end

      def update(dt)
        @blink.update(dt)
      end

      def draw(g_t)
        x, y, r = @state.get(g_t)
        G.set_color(r: 1, g: 1, b: 1)
        img = @blink.closed? ? @img_blink : @img_normal
        G.draw(drawable: img, x: x, y: y, r: r, sx: 1, sy: 1,
          ox: img.get_width / 2.0, oy: img.get_height / 2.0)
      end

      # Where the chain attaches.
      def attachment_point
        h = @body.get_world_point(x: 4, y: 90)
        [h[:x], h[:y]]
      end
    end

    # The chain of circle-shaped links spelling out the string, each joined to
    # the previous link and roped back to the Duckloon so it can't fly apart.
    class Chain
      def initialize(world, x, y, str, duckloon, images)
        @links = []
        draw_info = {
          "n" => { r: 11, img: images[:n] },
          "o" => { r: 11, img: images[:o] },
          "g" => { r: 11, img: images[:g] },
          "a" => { r: 11, img: images[:a] },
          "m" => { r: 11, img: images[:m] },
          "e" => { r: 11, img: images[:e] },
          " " => { r: 4,  img: nil },
          "#" => { r: 7,  img: images[:square] },
        }

        str.each_char.with_index do |ch, i|
          prev = i >= 1 ? @links[i - 1] : nil
          link = {}
          link[:x] = x
          link[:y] = y
          link[:info] = draw_info[ch]
          link[:radius] = link[:info][:r]
          link[:y] = prev[:y] + prev[:radius] + link[:radius] if prev

          link[:body] = P.new_body(world: world, x: link[:x], y: link[:y], type: "dynamic")
          link[:body].set_linear_damping(damping: 0.5)
          link[:body].set_angular_damping(damping: 0.5)
          link[:shape] = P.new_circle_shape(body: link[:body], radius: link[:radius])
          link[:shape].set_density(density: 0.1 / (i + 1))
          link[:state] = State.new(link[:body])

          # Every link is also roped to the Duckloon; otherwise the chain goes
          # haywire at higher speeds.
          if prev
            link[:joint] = P.new_revolute_joint(body1: link[:body], body2: prev[:body],
              x1: link[:x], y1: link[:y] - link[:radius] / 2.0)
            link[:join2] = P.new_rope_joint(body1: link[:body], body2: duckloon.body,
              x1: link[:x], y1: link[:y], x2: x, y2: y, max_length: link[:y] - y)
          else
            link[:joint] = P.new_revolute_joint(body1: link[:body], body2: duckloon.body,
              x1: link[:x], y1: link[:y])
          end

          @links << link
        end
      end

      def step(g_step)
        @links.each { |link| link[:state].save(link[:body], g_step) }
      end

      def update(dt); end

      def draw(g_t)
        rope = []
        @links.each do |link|
          x, y, = link[:state].get(g_t)
          rope << x << y
        end

        G.set_line_width(width: 3)
        G.set_color(r: 1, g: 1, b: 1, a: 0.7)
        G.line(points: rope)

        @links.each do |link|
          img = link[:info][:img]
          next unless img
          x, y, r = link[:state].get(g_t)
          G.set_color(r: 1, g: 1, b: 1)
          G.draw(drawable: img, x: x, y: y, r: r, sx: 1, sy: 1,
            ox: img.get_width / 2.0, oy: img.get_height / 2.0)
        end
      end
    end

    # A horizontal track of clouds scrolling in a repeating 1,2,3,4 pattern.
    class CloudTrack
      def initialize(x, y, offset, speed, img, cloud_images)
        @x = x
        @y = y
        @initial_offset = offset
        @h_spacing = 50
        @img = img
        @w = @h_spacing + @img.get_width
        @speed = speed # px/s
        @count = (G.get_width / @w + 2).to_i
        @initial_img = M.random(min: 1, max: 4)
        @cloud_images = cloud_images
      end

      def update(dt); end

      def draw(g_t)
        abs_offset = @initial_offset + @speed * g_t
        offset = abs_offset % @w
        G.set_color(r: 1, g: 1, b: 1, a: 0.3)
        (1..@count).each do |i|
          x = @x + (i - 1) * (@img.get_width + @h_spacing) + offset - @w
          img_no = (abs_offset / @w).floor
          G.draw(drawable: @cloud_images[(@initial_img + i - img_no) % 4], x: x, y: @y, r: -0.05)
        end
      end
    end

    # A stack of CloudTracks covering the window height.
    class Clouds
      def initialize(cloud_images)
        layer_height = 100
        @tracks = []
        base = cloud_images[0]
        max = (G.get_height / layer_height + 1).to_i
        (1..max).each do |i|
          @tracks << CloudTrack.new(0, 20 + (i - 1) * layer_height,
            base.get_width / 2.0 * i, 40, base, cloud_images)
        end
      end

      def draw(g_t)
        @tracks.each { |track| track.draw(g_t) }
      end
    end

    # Owns the world and drives the fixed-timestep simulation + drawing.
    class Scene
      STEP = 1.0 / 20 # 20 Hz physics.

      def initialize
        @g_t = 0.0
        @g_step = 0.0
        @images = {}
        @cloud_images = []
      end

      def load
        # love.window.getRendererInfo isn't ported; skip the title suffix it adds.
        G.set_background_color(r: 43 / 255.0, g: 165 / 255.0, b: 223 / 255.0)
        P.set_meter(scale: 64)

        dpiscale = Love::Window.get_dpi_scale > 1 ? 2 : 1
        chain = Love::NOGAME_ART["chain"][dpiscale]
        duck  = Love::NOGAME_ART["duckloon"][dpiscale]
        bg    = Love::NOGAME_ART["bg"][dpiscale]

        tex = lambda do |b64|
          bytes = Love::Data.decode(format: "base64", string: b64, container: "data")
          idata = Love::Image.new_image_data(file: bytes)
          G.new_image(file: idata, dpi_scale: dpiscale)
        end

        @images[:duckloon_normal] = tex.call(duck["normal"])
        @images[:duckloon_blink]  = tex.call(duck["blink"])
        %w[n o g a m e].each { |k| @images[k.to_sym] = tex.call(chain[k]) }
        @images[:square] = tex.call(chain["square"])
        @cloud_images = [tex.call(bg["cloud_1"]), tex.call(bg["cloud_2"]),
                         tex.call(bg["cloud_3"]), tex.call(bg["cloud_4"])]

        create_world
      end

      def create_world
        M.set_random_seed(seed: 12345)
        wx = G.get_width
        wy = G.get_height
        @world = P.new_world(gx: 0, gy: 9.81 * 64)
        @duckloon = Duckloon.new(@world, wx / 2.0, wy / 2.0 - 100, @images)
        ax, ay = @duckloon.attachment_point
        @chain = Chain.new(@world, ax, ay, "  n o # g a m e # ", @duckloon, @images)
        @clouds = Clouds.new(@cloud_images)
        @objs = [@chain, @duckloon]
      end

      def update(dt)
        @g_t += dt
        while @g_t > @g_step
          @world.update(dt: STEP)
          @g_step += STEP
          @objs.each { |o| o.step(@g_step) }
        end
        @objs.each { |o| o.update(dt) }
      end

      def draw
        @clouds.draw(@g_t)
        @objs.each { |o| o.draw(@g_t) }
      end

      def keypressed(key)
        Love::Event.quit if key == "escape"
      end

      def mousepressed(_x, _y, _button, istouch, clicks)
        # Double-tap a touch screen to exit. The ported show_message_box has no
        # button-choice form, so confirm-then-quit collapses to an info box + quit.
        return unless istouch && clicks == 2
        Love::Window.show_message_box(title: "Exit No-Game Screen", message: "", type: "info")
        Love::Event.quit
      end

      def resize
        create_world
        @g_step = @g_t
      end

      def conf(c)
        c[:title] = "LÖVE"
        c[:window] ||= {}
        c[:window][:resizable] = true
      end
    end
  end

  # Installs the no-game screen's callbacks on Love, mirroring boot.lua's
  # `require("love.nogame")()`. define_singleton_method makes them public, so the
  # callbacks.rb run loop's `respond_to?` checks pick them up.
  def self.nogame
    scene = NoGameScreen::Scene.new
    define_singleton_method(:conf)         { |c| scene.conf(c) }
    define_singleton_method(:load)         { |*| scene.load }
    define_singleton_method(:update)       { |dt| scene.update(dt) }
    define_singleton_method(:draw)         { scene.draw }
    define_singleton_method(:keypressed)   { |key, *| scene.keypressed(key) }
    define_singleton_method(:mousepressed) { |*a| scene.mousepressed(*a) }
    define_singleton_method(:resize)       { |*| scene.resize }
    nil
  end
end
